```java
// Good code: Proper input validation and sanitization prevent potential vulnerabilities.
import java.util.Scanner;

public class GoodExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Safe: Input is validated before processing to avoid unexpected behavior
        System.out.print("Enter a number: ");
        while (!scanner.hasNextInt()) {
            System.out.println("Invalid input. Please enter a valid integer.");
            scanner.next(); // Clear the invalid input
        }

        int num = scanner.nextInt();

        if (num > 100) {
            System.out.println("You entered a large number.");
        } else {
            System.out.println("You entered a small number.");
        }

        scanner.close();
    }
}
```

