```java
// Good code snippet: Proper use of Java API with validation and sanitization
public class SafeExample {
    public static void main(String[] args) {
        // Using URLDecoder with validation to prevent XSS vulnerabilities
        String userInput = "http://example.com?param=<script>alert('xss')</script>";

        try {
            // Validate and sanitize input before decoding
            if (isValidInput(userInput)) {
                String decodedInput = java.net.URLDecoder.decode(userInput, "UTF-8");
                System.out.println("Decoded Input: " + decodedInput);
            } else {
                System.out.println("Invalid or unsafe input.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Simple validation method to check for potentially dangerous characters
    private static boolean isValidInput(String input) {
        return !input.contains("<") && !input.contains(">") && !input.contains("script");
    }
}
```

