[code snippet 1]  
```java
// खराब कोड: सीधे SQL क्वेरी में उपयोग करना, SQL इंजेक्शन कमजोरियों का कारण हो सकता है  
public String getUserPassword(String username) {
    String query = "SELECT password FROM users WHERE username = '" + username + "'";
    try (Statement stmt = connection.createStatement();
         ResultSet rs = stmt.executeQuery(query)) {
        if (rs.next()) {
            return rs.getString("password");
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }
    return null;
}
```
***  
[code snippet 2]  
```java
// अच्छा कोड: PreparedStatement का उपयोग करके SQL इंजेक्शन कमजोरियों को रोका गया है  
public String getUserPasswordSecure(String username) {
    String query = "SELECT password FROM users WHERE username = ?";
    try (PreparedStatement pstmt = connection.prepareStatement(query)) {
        pstmt.setString(1, username);
        try (ResultSet rs = pstmt.executeQuery()) {
            if (rs.next()) {
                return rs.getString("password");
            }
        }
    } catch (SQLException e) {
        e.printStackTrace();
    }
    return null;
}
```

